SELECT *
  FROM SALES
 PIVOT (SUM(AMT) FOR QTR IN ('Q1' AS Q1, 'Q2' AS Q2));

SELECT YR, QTR, AMT
  FROM QSALES
UNPIVOT (AMT FOR QTR IN (Q1, Q2, Q3));

SELECT YR, QTR, AMT
  FROM QS
UNPIVOT (AMT FOR QTR IN (Q1, Q2, Q3));

SELECT *
  FROM SALES2
 PIVOT (SUM(AMT) FOR QTR IN ('Q1' AS Q1, 'Q2' AS Q2));
